#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin>>n;

    struct Piece{ int k; vector<pair<int,int>> cells; };
    vector<Piece> pieces(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for(int j=0;j<pieces[i].k;j++)
            cin>>pieces[i].cells[j].first>>pieces[i].cells[j].second;
        totalCells+=pieces[i].k;
    }

    struct Ori{ vector<pair<int,int>> cells; int w,h,r,f; };
    vector<vector<Ori>> allOris(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                vector<pair<int,int>> tc;
                for(auto [x,y]:pieces[i].cells){
                    int nx=x,ny=y;
                    if(f) nx=-nx;
                    for(int q=0;q<r;q++){int tmp=nx;nx=ny;ny=-tmp;}
                    tc.push_back({nx,ny});
                }
                int mnx=INT_MAX,mny=INT_MAX;
                for(auto[x,y]:tc){mnx=min(mnx,x);mny=min(mny,y);}
                for(auto&[x,y]:tc){x-=mnx;y-=mny;}
                sort(tc.begin(),tc.end());
                if(seen.insert(tc).second){
                    int w=0,h=0;
                    for(auto[x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                    allOris[i].push_back({tc,w,h,r,f});
                }
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return pieces[a].k>pieces[b].k;});

    auto startTime=chrono::steady_clock::now();
    auto elapsed=[&]()->double{
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    double sqrtA=sqrt((double)totalCells);

    vector<int> candW;
    for(int w=max(1,(int)(sqrtA*0.5));w<=(int)(sqrtA*3.0)+1;w++) candW.push_back(w);
    // Also add some larger
    for(int w=(int)(sqrtA*3.0)+2;w<=totalCells&&w<=(int)(sqrtA*5.0);w+=max(1,(int)(sqrtA*0.2)))
        candW.push_back(w);
    // Ensure min width fits largest piece
    int minPW=0;
    for(int i=0;i<n;i++) for(auto&o:allOris[i]) minPW=max(minPW,min(o.w,o.h));

    sort(candW.begin(),candW.end());
    candW.erase(unique(candW.begin(),candW.end()),candW.end());

    long long bestArea=(long long)4e18;
    int bestH=0,bestW=0;
    struct PR{int x,y,r,f;};
    vector<PR> bestPl(n);

    for(int W:candW){
        if(W<minPW) continue;
        if(elapsed()>8.5 && bestArea<(long long)4e18) break;

        int maxH=max((totalCells+W-1)/W*3+50, 200);
        maxH=min(maxH,totalCells+50);

        vector<int> hmap(W,0);
        vector<vector<bool>> grid(W,vector<bool>(maxH,false));
        vector<PR> pl(n);
        int curMaxY=0;
        bool failed=false;

        for(int idx=0;idx<n&&!failed;idx++){
            int pi=order[idx];
            int bestScore=INT_MAX;
            int bx=-1,by=-1,boi=-1;

            for(int oi=0;oi<(int)allOris[pi].size();oi++){
                auto&ori=allOris[pi][oi];
                if(ori.w>W) continue;

                for(int x=0;x<=W-ori.w;x++){
                    int minY=0;
                    for(auto[cx,cy]:ori.cells)
                        minY=max(minY,hmap[x+cx]-cy);

                    int topY=0;
                    for(auto[cx,cy]:ori.cells) topY=max(topY,minY+cy+1);
                    if(topY>maxH) continue;

                    bool ok=true;
                    for(auto[cx,cy]:ori.cells){
                        int py=minY+cy;
                        if(py<0||py>=maxH||grid[x+cx][py]){ok=false;break;}
                    }
                    if(!ok) continue;

                    int score=topY*10000+x;
                    if(score<bestScore){
                        bestScore=score;
                        bx=x;by=minY;boi=oi;
                    }
                }
            }

            if(bx==-1){failed=true;break;}

            auto&ori=allOris[pi][boi];
            for(auto[cx,cy]:ori.cells){
                grid[bx+cx][by+cy]=true;
                hmap[bx+cx]=max(hmap[bx+cx],by+cy+1);
                curMaxY=max(curMaxY,by+cy+1);
            }
            pl[pi]={bx,by,ori.r,ori.f};
        }

        if(failed) continue;

        long long area=(long long)W*curMaxY;
        if(area<bestArea){
            bestArea=area;
            bestH=curMaxY;
            bestW=W;
            bestPl=pl;
        }
    }

    if(bestArea>=(long long)4e18){
        // fallback: line them up
        int cx=0;
        bestH=0;
        for(int i=0;i<n;i++){
            auto&ori=allOris[i][0];
            bestPl[i]={cx,0,ori.r,ori.f};
            cx+=ori.w;
            bestH=max(bestH,ori.h);
        }
        bestW=cx;
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++)
        cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
    return 0;
}
